/// A model from any provider — an .rlxp package, a plugin's family runner
/// (LLMs, speech, vision, …) — opened by path or id and run by name.
public final class Model {
    let handle: OpaquePointer

    init(handle: OpaquePointer) { self.handle = handle }

    deinit { rlx_model_free(handle) }

    /// Open `source` (a path or id). options: {device, provider, …the provider's own}.
    public static func `open`(_ source: String, options: [String: Any]? = nil) throws -> Model {
        let optionsJ = try jsonText(options)
        var out0: OpaquePointer? = nil
        try withOptionalCString(optionsJ) { optionsP in
            try check(rlx_model_open(source, optionsP, &out0))
        }
        return Model(handle: out0!)
    }

    /// {provider, family, task, device, inputs: [{name, dtype, shape}], outputs, metadata}.
    @discardableResult
    public func info() throws -> [String: Any] {
        var out0: UnsafeMutablePointer<CChar>? = nil
        try check(rlx_model_info(handle, &out0))
        return try takeObject(out0)
    }

    /// The task: "graph", "text-generation", "speech-recognition", ….
    public func task() throws -> String {
        var out0: UnsafeMutablePointer<CChar>? = nil
        try check(rlx_model_task(handle, &out0))
        return takeString(out0)
    }

    /// f32 tensors in, f32 tensors out. options: {shapes: {name: dims}, …the model's own}.
    public func run(_ inputs: [String: [Float]], options: [String: Any]? = nil) throws -> [[Float]] {
        let optionsJ = try jsonText(options)
        var out0: OpaquePointer? = nil
        try withInputs(inputs) { inputsNames, inputsData, inputsLens, inputsN in
            try withOptionalCString(optionsJ) { optionsP in
                try check(rlx_model_run(handle, inputsNames, inputsData, inputsLens, inputsN, optionsP, &out0))
            }
        }
        return try collectOutputs(out0!)
    }

    /// Tensors of any dtype in (bytes + dtype), out the same way.
    public func runTyped(_ inputs: [String: TypedTensor], options: [String: Any]? = nil) throws -> [TypedTensor] {
        let optionsJ = try jsonText(options)
        var out0: OpaquePointer? = nil
        try withTypedInputs(inputs) { inputsNames, inputsData, inputsLens, inputsTypes, inputsN in
            try withOptionalCString(optionsJ) { optionsP in
                try check(rlx_model_run_typed(handle, inputsNames, inputsData, inputsLens, inputsTypes, inputsN, optionsP, &out0))
            }
        }
        return try takeTypedOutputs(out0!)
    }

    /// Dims of each output of the last run.
    public func outputShapes() throws -> [[Int]] {
        var out0: UnsafeMutablePointer<CChar>? = nil
        try check(rlx_model_output_shapes(handle, &out0))
        return try decodeJSON([[Int]].self, takeString(out0))
    }

    /// Names of the outputs of the last run.
    public func outputNames() throws -> [String] {
        var out0: UnsafeMutablePointer<CChar>? = nil
        try check(rlx_model_output_names(handle, &out0))
        return try decodeJSON([String].self, takeString(out0))
    }

    /// A language model's last-position logits after `ids`.
    public func predictLogits(_ ids: [UInt32]) throws -> [Float] {
        var out0: RlxF32s = RlxF32s(ptr: nil, len: 0)
        try check(rlx_model_predict_logits(handle, ids, ids.count, &out0))
        return takeF32s(out0)
    }

    /// A language model's next ids after `ids`. options: {temperature, top_p, top_k, seed, stop_ids}.
    public func generate(_ ids: [UInt32], maxTokens: Int = 16, options: [String: Any]? = nil) throws -> [UInt32] {
        let optionsJ = try jsonText(options)
        var out0: RlxU32s = RlxU32s(ptr: nil, len: 0)
        try withOptionalCString(optionsJ) { optionsP in
            try check(rlx_model_generate(handle, ids, ids.count, maxTokens, optionsP, &out0))
        }
        return takeU32s(out0)
    }

    /// Text in, text out, for a model with a tokenizer. options: {max_tokens, temperature, …}.
    public func generateText(_ prompt: String, options: [String: Any]? = nil) throws -> String {
        let optionsJ = try jsonText(options)
        var out0: UnsafeMutablePointer<CChar>? = nil
        try withOptionalCString(optionsJ) { optionsP in
            try check(rlx_model_generate_text(handle, prompt, optionsP, &out0))
        }
        return takeString(out0)
    }

    /// A reply to `messages` ([{role, content}, …], or one string), with the
    /// model's chat template applied. options: as generate_text.
    public func chat(_ messages: Any, options: [String: Any]? = nil) throws -> String {
        let messagesJ = try jsonText(messages)
        let optionsJ = try jsonText(options)
        var out0: UnsafeMutablePointer<CChar>? = nil
        try withOptionalCString(messagesJ) { messagesP in
            try withOptionalCString(optionsJ) { optionsP in
                try check(rlx_model_chat(handle, messagesP, optionsP, &out0))
            }
        }
        return takeString(out0)
    }

    /// The text of mono `audio` at `sample_rate`, for a speech-recognition model.
    public func transcribe(_ audio: [Float], sampleRate: UInt32 = 16000, options: [String: Any]? = nil) throws -> String {
        let optionsJ = try jsonText(options)
        var out0: UnsafeMutablePointer<CChar>? = nil
        try withOptionalCString(optionsJ) { optionsP in
            try check(rlx_model_transcribe(handle, audio, audio.count, sampleRate, optionsP, &out0))
        }
        return takeString(out0)
    }

    /// `text` spoken, for a text-to-speech model: mono samples and their rate.
    @discardableResult
    public func synthesize(_ text: String, options: [String: Any]? = nil) throws -> (audio: [Float], sampleRate: UInt32) {
        let optionsJ = try jsonText(options)
        var out0: RlxF32s = RlxF32s(ptr: nil, len: 0)
        var out1: UInt32 = 0
        try withOptionalCString(optionsJ) { optionsP in
            try check(rlx_model_synthesize(handle, text, optionsP, &out0, &out1))
        }
        return (audio: takeF32s(out0), sampleRate: out1)
    }

    /// One vector per text ([[f32, …], …]), for an embedding model.
    public func embed(_ texts: [String], options: [String: Any]? = nil) throws -> Any {
        let optionsJ = try jsonText(options)
        var out0: UnsafeMutablePointer<CChar>? = nil
        try withCStrings(texts) { textsP, textsN in
            try withOptionalCString(optionsJ) { optionsP in
                try check(rlx_model_embed(handle, textsP, textsN, optionsP, &out0))
            }
        }
        return try takeJSON(out0)
    }
}
